import "./AdrList.css";

export type Adr = { id: string; title: string };

// Discriminated union instead of `adrs: Adr[] | null` + `isLoading: boolean` —
// makes "loading with stale data" and "ready with no data" unrepresentable.
export type AdrListState =
  | { status: "loading" }
  | { status: "ready"; adrs: Adr[] };

const SKELETON_ROW_COUNT = 3;

export function AdrList({ state }: { state: AdrListState }) {
  if (state.status === "loading") {
    // Renders synchronously with the component, so the skeleton is on
    // screen well within the 100ms budget while decisions load from
    // .ai-state/decisions/ — no timer or delay logic needed.
    return (
      <ul
        className="adr-list adr-list--loading"
        aria-busy="true"
        aria-live="polite"
        aria-label="Loading decisions"
      >
        {Array.from({ length: SKELETON_ROW_COUNT }, (_, index) => (
          <li key={index} className="adr-list__skeleton-item" />
        ))}
      </ul>
    );
  }

  return (
    <ul className="adr-list">
      {state.adrs.map((adr) => <li key={adr.id}>{adr.title}</li>)}
    </ul>
  );
}

