.adr-list--loading {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  list-style: none;
  margin: 0;
  padding: 0;
}

.adr-list__skeleton-item {
  height: 1.25rem;
  border-radius: var(--radius-1);
  background: currentColor;
  opacity: 0.12;
  animation: adr-list-pulse 1.4s ease-in-out infinite;
}

@keyframes adr-list-pulse {
  0%,
  100% {
    opacity: 0.12;
  }
  50% {
    opacity: 0.24;
  }
}

@media (prefers-reduced-motion: reduce) {
  .adr-list__skeleton-item {
    animation: none;
  }
}
